CREATE TABLE IF NOT EXISTS "patients" (
	-- Internal surrogate key. Never printed on a wristband.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- MRN — the identifier staff actually quote. Unique for the lifetime of the organisation.
	"medical_record_number" VARCHAR(24) NOT NULL UNIQUE,
	-- First name as recorded on identity documents.
	"given_name" VARCHAR(100) NOT NULL,
	-- Surname.
	"family_name" VARCHAR(100) NOT NULL,
	-- Used with name for identity verification and for paediatric dosing.
	"date_of_birth" DATE NOT NULL,
	-- Recorded separately from gender identity because lab reference ranges depend on it.
	"sex_at_birth" VARCHAR(16),
	-- How the patient identifies. Used for correspondence and address.
	"gender_identity" VARCHAR(32),
	-- Contact number for appointment reminders.
	"phone" VARCHAR(32),
	-- Portal login and correspondence address.
	"email" VARCHAR(320),
	-- Date of death. Set rather than deleting the record.
	"deceased_on" DATE,
	-- Registration time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "patients" IS 'The person receiving care. Patient records are never deleted — retention is set by regulation, and clinical history has to survive a name change, a merge or a death.';
COMMENT ON COLUMN "patients"."id" IS 'Internal surrogate key. Never printed on a wristband.';
COMMENT ON COLUMN "patients"."medical_record_number" IS 'MRN — the identifier staff actually quote. Unique for the lifetime of the organisation.';
COMMENT ON COLUMN "patients"."given_name" IS 'First name as recorded on identity documents.';
COMMENT ON COLUMN "patients"."family_name" IS 'Surname.';
COMMENT ON COLUMN "patients"."date_of_birth" IS 'Used with name for identity verification and for paediatric dosing.';
COMMENT ON COLUMN "patients"."sex_at_birth" IS 'Recorded separately from gender identity because lab reference ranges depend on it.';
COMMENT ON COLUMN "patients"."gender_identity" IS 'How the patient identifies. Used for correspondence and address.';
COMMENT ON COLUMN "patients"."phone" IS 'Contact number for appointment reminders.';
COMMENT ON COLUMN "patients"."email" IS 'Portal login and correspondence address.';
COMMENT ON COLUMN "patients"."deceased_on" IS 'Date of death. Set rather than deleting the record.';
COMMENT ON COLUMN "patients"."created_at" IS 'Registration time.';

CREATE INDEX "idx_patients_name_dob"
ON "patients" ("family_name", "date_of_birth");

CREATE TABLE IF NOT EXISTS "departments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Department name, e.g. Cardiology.
	"name" VARCHAR(120) NOT NULL,
	-- Short internal code used in scheduling and billing.
	"code" VARCHAR(20) NOT NULL UNIQUE,
	-- Building and floor, for wayfinding.
	"location" VARCHAR(120),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "departments" IS 'Organisational unit that owns clinics, wards and providers. Kept as a table so reporting can roll up by department without string matching.';
COMMENT ON COLUMN "departments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "departments"."name" IS 'Department name, e.g. Cardiology.';
COMMENT ON COLUMN "departments"."code" IS 'Short internal code used in scheduling and billing.';
COMMENT ON COLUMN "departments"."location" IS 'Building and floor, for wayfinding.';

CREATE TABLE IF NOT EXISTS "providers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Primary department. Null for locums and visiting staff.
	"department_id" BIGINT,
	-- National provider identifier, where the jurisdiction issues one.
	"npi_number" VARCHAR(20) UNIQUE,
	-- Name as it appears on prescriptions and notes.
	"full_name" VARCHAR(160) NOT NULL,
	-- physician | nurse | pharmacist | technician | admin. Drives what the clinician may sign.
	"role" VARCHAR(40) NOT NULL,
	-- Clinical specialty, e.g. cardiology.
	"specialty" VARCHAR(80),
	-- False when the clinician leaves; their signed notes remain attributed to them.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "providers" IS 'Anyone who can be named on a clinical record. Providers are deactivated rather than deleted, because every note they signed still points here.';
COMMENT ON COLUMN "providers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "providers"."department_id" IS 'Primary department. Null for locums and visiting staff.';
COMMENT ON COLUMN "providers"."npi_number" IS 'National provider identifier, where the jurisdiction issues one.';
COMMENT ON COLUMN "providers"."full_name" IS 'Name as it appears on prescriptions and notes.';
COMMENT ON COLUMN "providers"."role" IS 'physician | nurse | pharmacist | technician | admin. Drives what the clinician may sign.';
COMMENT ON COLUMN "providers"."specialty" IS 'Clinical specialty, e.g. cardiology.';
COMMENT ON COLUMN "providers"."is_active" IS 'False when the clinician leaves; their signed notes remain attributed to them.';

CREATE INDEX "idx_providers_department_active"
ON "providers" ("department_id", "is_active");

CREATE TABLE IF NOT EXISTS "appointments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient being seen.
	"patient_id" BIGINT NOT NULL,
	-- Clinician booked. Null for clinic-level slots assigned on the day.
	"provider_id" BIGINT,
	-- Department providing the slot.
	"department_id" BIGINT NOT NULL,
	-- Slot start. Stored in UTC; clinics render in local time.
	"scheduled_start" TIMESTAMP NOT NULL,
	-- Slot length, driven by appointment type.
	"duration_minutes" INTEGER NOT NULL DEFAULT 15,
	-- new_patient | follow_up | procedure | telehealth.
	"appointment_type" VARCHAR(40) NOT NULL,
	-- booked | arrived | completed | cancelled | no_show. No-show rates are a reported metric, so the state is kept rather than deleting the row.
	"status" VARCHAR(24) NOT NULL DEFAULT 'booked',
	-- Reason for visit, as given by the patient at booking.
	"reason" VARCHAR(255),
	-- Booking time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "appointments" IS 'A planned contact. Appointments are administrative: the clinical record of what happened is an encounter, and a cancelled appointment never produces one.';
COMMENT ON COLUMN "appointments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "appointments"."patient_id" IS 'Patient being seen.';
COMMENT ON COLUMN "appointments"."provider_id" IS 'Clinician booked. Null for clinic-level slots assigned on the day.';
COMMENT ON COLUMN "appointments"."department_id" IS 'Department providing the slot.';
COMMENT ON COLUMN "appointments"."scheduled_start" IS 'Slot start. Stored in UTC; clinics render in local time.';
COMMENT ON COLUMN "appointments"."duration_minutes" IS 'Slot length, driven by appointment type.';
COMMENT ON COLUMN "appointments"."appointment_type" IS 'new_patient | follow_up | procedure | telehealth.';
COMMENT ON COLUMN "appointments"."status" IS 'booked | arrived | completed | cancelled | no_show. No-show rates are a reported metric, so the state is kept rather than deleting the row.';
COMMENT ON COLUMN "appointments"."reason" IS 'Reason for visit, as given by the patient at booking.';
COMMENT ON COLUMN "appointments"."created_at" IS 'Booking time.';

CREATE INDEX "idx_appointments_provider_start"
ON "appointments" ("provider_id", "scheduled_start");
CREATE INDEX "idx_appointments_patient_start"
ON "appointments" ("patient_id", "scheduled_start");

CREATE TABLE IF NOT EXISTS "encounters" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient seen.
	"patient_id" BIGINT NOT NULL,
	-- Originating appointment, when the encounter was planned. Null for walk-ins and emergencies.
	"appointment_id" BIGINT,
	-- Clinician responsible for the episode.
	"attending_provider_id" BIGINT,
	-- Where care was delivered.
	"department_id" BIGINT NOT NULL,
	-- ambulatory | emergency | inpatient | virtual.
	"encounter_class" VARCHAR(24) NOT NULL,
	-- Start of the episode of care.
	"admitted_at" TIMESTAMP NOT NULL,
	-- End of the episode. Null while the patient is still under care.
	"discharged_at" TIMESTAMP,
	-- home | transferred | admitted | deceased, recorded at discharge.
	"disposition" VARCHAR(40),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "encounters" IS 'One episode of care, and the anchor for everything clinical. Diagnoses, prescriptions and observations all hang off an encounter so that any finding can be traced to the visit that produced it.';
COMMENT ON COLUMN "encounters"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "encounters"."patient_id" IS 'Patient seen.';
COMMENT ON COLUMN "encounters"."appointment_id" IS 'Originating appointment, when the encounter was planned. Null for walk-ins and emergencies.';
COMMENT ON COLUMN "encounters"."attending_provider_id" IS 'Clinician responsible for the episode.';
COMMENT ON COLUMN "encounters"."department_id" IS 'Where care was delivered.';
COMMENT ON COLUMN "encounters"."encounter_class" IS 'ambulatory | emergency | inpatient | virtual.';
COMMENT ON COLUMN "encounters"."admitted_at" IS 'Start of the episode of care.';
COMMENT ON COLUMN "encounters"."discharged_at" IS 'End of the episode. Null while the patient is still under care.';
COMMENT ON COLUMN "encounters"."disposition" IS 'home | transferred | admitted | deceased, recorded at discharge.';

CREATE INDEX "idx_encounters_patient_admitted"
ON "encounters" ("patient_id", "admitted_at");
CREATE INDEX "idx_encounters_department_admitted"
ON "encounters" ("department_id", "admitted_at");

CREATE TABLE IF NOT EXISTS "conditions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient the condition belongs to.
	"patient_id" BIGINT NOT NULL,
	-- Encounter at which it was recorded. Null for history taken at registration.
	"encounter_id" BIGINT,
	-- Terminology the code comes from, e.g. ICD-10 or SNOMED CT.
	"code_system" VARCHAR(20) NOT NULL DEFAULT 'ICD-10',
	-- The code itself. Codes, not free text, are what billing and analytics can use.
	"code" VARCHAR(24) NOT NULL,
	-- Human-readable term at the time of coding, snapshotted so a terminology update cannot rewrite history.
	"display_name" VARCHAR(255) NOT NULL,
	-- active | resolved | remission.
	"clinical_status" VARCHAR(24) NOT NULL DEFAULT 'active',
	-- When the condition began, as best established.
	"onset_date" DATE,
	-- When the entry was made.
	"recorded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "conditions" IS 'The problem list. Coding against a published terminology is what makes a diagnosis comparable across visits, hospitals and research extracts.';
COMMENT ON COLUMN "conditions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "conditions"."patient_id" IS 'Patient the condition belongs to.';
COMMENT ON COLUMN "conditions"."encounter_id" IS 'Encounter at which it was recorded. Null for history taken at registration.';
COMMENT ON COLUMN "conditions"."code_system" IS 'Terminology the code comes from, e.g. ICD-10 or SNOMED CT.';
COMMENT ON COLUMN "conditions"."code" IS 'The code itself. Codes, not free text, are what billing and analytics can use.';
COMMENT ON COLUMN "conditions"."display_name" IS 'Human-readable term at the time of coding, snapshotted so a terminology update cannot rewrite history.';
COMMENT ON COLUMN "conditions"."clinical_status" IS 'active | resolved | remission.';
COMMENT ON COLUMN "conditions"."onset_date" IS 'When the condition began, as best established.';
COMMENT ON COLUMN "conditions"."recorded_at" IS 'When the entry was made.';

CREATE INDEX "idx_conditions_patient_status"
ON "conditions" ("patient_id", "clinical_status");
CREATE INDEX "idx_conditions_code"
ON "conditions" ("code_system", "code");

CREATE TABLE IF NOT EXISTS "medications" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Drug code, e.g. RxNorm RXCUI or dm+d identifier.
	"code" VARCHAR(24) NOT NULL UNIQUE,
	-- Preferred display name including strength.
	"name" VARCHAR(200) NOT NULL,
	-- tablet | capsule | solution | inhaler.
	"form" VARCHAR(40),
	-- Strength as dispensed, e.g. 500 mg.
	"strength" VARCHAR(60),
	-- Controlled substance flag; drives extra prescribing checks.
	"is_controlled" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "medications" IS 'Drug catalogue. Prescriptions reference this rather than storing a drug name, so an interaction check has something structured to work with.';
COMMENT ON COLUMN "medications"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "medications"."code" IS 'Drug code, e.g. RxNorm RXCUI or dm+d identifier.';
COMMENT ON COLUMN "medications"."name" IS 'Preferred display name including strength.';
COMMENT ON COLUMN "medications"."form" IS 'tablet | capsule | solution | inhaler.';
COMMENT ON COLUMN "medications"."strength" IS 'Strength as dispensed, e.g. 500 mg.';
COMMENT ON COLUMN "medications"."is_controlled" IS 'Controlled substance flag; drives extra prescribing checks.';

CREATE TABLE IF NOT EXISTS "prescriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient prescribed for.
	"patient_id" BIGINT NOT NULL,
	-- Encounter at which it was prescribed.
	"encounter_id" BIGINT,
	-- Drug prescribed.
	"medication_id" BIGINT NOT NULL,
	-- Clinician who signed. Legally required and never nullable.
	"prescriber_id" BIGINT NOT NULL,
	-- Dose per administration, e.g. 500 mg.
	"dose" VARCHAR(60) NOT NULL,
	-- How often, e.g. twice daily.
	"frequency" VARCHAR(60) NOT NULL,
	-- oral | iv | topical | inhaled.
	"route" VARCHAR(40),
	-- Units dispensed.
	"quantity" INTEGER,
	-- Number of repeats permitted.
	"refills_allowed" INTEGER NOT NULL DEFAULT 0,
	-- First day of the course.
	"start_date" DATE NOT NULL,
	-- Last day. Null for ongoing repeat medication.
	"end_date" DATE,
	-- active | completed | stopped | cancelled.
	"status" VARCHAR(24) NOT NULL DEFAULT 'active',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "prescriptions" IS 'A signed order for a drug. Stopping a prescription sets a status and an end date rather than deleting it — what was prescribed, and when it stopped, is part of the record.';
COMMENT ON COLUMN "prescriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "prescriptions"."patient_id" IS 'Patient prescribed for.';
COMMENT ON COLUMN "prescriptions"."encounter_id" IS 'Encounter at which it was prescribed.';
COMMENT ON COLUMN "prescriptions"."medication_id" IS 'Drug prescribed.';
COMMENT ON COLUMN "prescriptions"."prescriber_id" IS 'Clinician who signed. Legally required and never nullable.';
COMMENT ON COLUMN "prescriptions"."dose" IS 'Dose per administration, e.g. 500 mg.';
COMMENT ON COLUMN "prescriptions"."frequency" IS 'How often, e.g. twice daily.';
COMMENT ON COLUMN "prescriptions"."route" IS 'oral | iv | topical | inhaled.';
COMMENT ON COLUMN "prescriptions"."quantity" IS 'Units dispensed.';
COMMENT ON COLUMN "prescriptions"."refills_allowed" IS 'Number of repeats permitted.';
COMMENT ON COLUMN "prescriptions"."start_date" IS 'First day of the course.';
COMMENT ON COLUMN "prescriptions"."end_date" IS 'Last day. Null for ongoing repeat medication.';
COMMENT ON COLUMN "prescriptions"."status" IS 'active | completed | stopped | cancelled.';

CREATE INDEX "idx_prescriptions_patient_status"
ON "prescriptions" ("patient_id", "status");

CREATE TABLE IF NOT EXISTS "observations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient measured.
	"patient_id" BIGINT NOT NULL,
	-- Encounter during which the measurement was taken.
	"encounter_id" BIGINT,
	-- Terminology for the observation code, usually LOINC.
	"code_system" VARCHAR(20) NOT NULL DEFAULT 'LOINC',
	-- What was measured, e.g. 8867-4 for heart rate.
	"code" VARCHAR(24) NOT NULL,
	-- Readable name of the measurement.
	"display_name" VARCHAR(160) NOT NULL,
	-- Numeric result. Null for qualitative results.
	"value_numeric" NUMERIC(14,4),
	-- Textual result for qualitative observations, e.g. positive.
	"value_text" VARCHAR(255),
	-- UCUM unit for value_numeric.
	"unit" VARCHAR(32),
	-- Normal range at the reporting lab, snapshotted with the result.
	"reference_range" VARCHAR(60),
	-- high | low | critical, as reported by the lab.
	"abnormal_flag" VARCHAR(12),
	-- When the measurement was taken, which is not when it was entered.
	"observed_at" TIMESTAMP NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "observations" IS 'Vitals and lab results in one narrow table. A single observation row per measurement — rather than a wide column per test — is what lets a new lab panel be added without a migration.';
COMMENT ON COLUMN "observations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "observations"."patient_id" IS 'Patient measured.';
COMMENT ON COLUMN "observations"."encounter_id" IS 'Encounter during which the measurement was taken.';
COMMENT ON COLUMN "observations"."code_system" IS 'Terminology for the observation code, usually LOINC.';
COMMENT ON COLUMN "observations"."code" IS 'What was measured, e.g. 8867-4 for heart rate.';
COMMENT ON COLUMN "observations"."display_name" IS 'Readable name of the measurement.';
COMMENT ON COLUMN "observations"."value_numeric" IS 'Numeric result. Null for qualitative results.';
COMMENT ON COLUMN "observations"."value_text" IS 'Textual result for qualitative observations, e.g. positive.';
COMMENT ON COLUMN "observations"."unit" IS 'UCUM unit for value_numeric.';
COMMENT ON COLUMN "observations"."reference_range" IS 'Normal range at the reporting lab, snapshotted with the result.';
COMMENT ON COLUMN "observations"."abnormal_flag" IS 'high | low | critical, as reported by the lab.';
COMMENT ON COLUMN "observations"."observed_at" IS 'When the measurement was taken, which is not when it was entered.';

CREATE INDEX "idx_observations_patient_code_time"
ON "observations" ("patient_id", "code", "observed_at");

CREATE TABLE IF NOT EXISTS "allergies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Patient the allergy belongs to.
	"patient_id" BIGINT NOT NULL,
	-- Coded substance, so prescribing checks can match against drug codes.
	"substance_code" VARCHAR(24) NOT NULL,
	-- Readable substance name.
	"substance_name" VARCHAR(160) NOT NULL,
	-- Observed reaction, e.g. anaphylaxis.
	"reaction" VARCHAR(255),
	-- mild | moderate | severe.
	"severity" VARCHAR(16),
	-- Clinician who recorded it.
	"recorded_by_id" BIGINT,
	-- When it was recorded.
	"recorded_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "allergies" IS 'Allergy list, coded so that prescribing can be blocked automatically. This is the table most likely to be read on an emergency screen, which is why it is small and directly keyed by patient.';
COMMENT ON COLUMN "allergies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "allergies"."patient_id" IS 'Patient the allergy belongs to.';
COMMENT ON COLUMN "allergies"."substance_code" IS 'Coded substance, so prescribing checks can match against drug codes.';
COMMENT ON COLUMN "allergies"."substance_name" IS 'Readable substance name.';
COMMENT ON COLUMN "allergies"."reaction" IS 'Observed reaction, e.g. anaphylaxis.';
COMMENT ON COLUMN "allergies"."severity" IS 'mild | moderate | severe.';
COMMENT ON COLUMN "allergies"."recorded_by_id" IS 'Clinician who recorded it.';
COMMENT ON COLUMN "allergies"."recorded_at" IS 'When it was recorded.';

CREATE UNIQUE INDEX "uq_allergies_patient_substance"
ON "allergies" ("patient_id", "substance_code");

CREATE TABLE IF NOT EXISTS "insurance_policies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Covered patient.
	"patient_id" BIGINT NOT NULL,
	-- Insurer name.
	"payer_name" VARCHAR(160) NOT NULL,
	-- Membership identifier quoted on claims.
	"member_number" VARCHAR(60) NOT NULL,
	-- Employer group identifier, where applicable.
	"group_number" VARCHAR(60),
	-- 1 for primary, 2 for secondary. Claims are submitted in this order.
	"coverage_priority" INTEGER NOT NULL DEFAULT 1,
	-- Cover start date.
	"effective_from" DATE NOT NULL,
	-- Cover end date. Null while active.
	"effective_to" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "insurance_policies" IS 'Coverage over time. Old policies are kept because a claim for last year is adjudicated against the policy that was in force then, not the current one.';
COMMENT ON COLUMN "insurance_policies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "insurance_policies"."patient_id" IS 'Covered patient.';
COMMENT ON COLUMN "insurance_policies"."payer_name" IS 'Insurer name.';
COMMENT ON COLUMN "insurance_policies"."member_number" IS 'Membership identifier quoted on claims.';
COMMENT ON COLUMN "insurance_policies"."group_number" IS 'Employer group identifier, where applicable.';
COMMENT ON COLUMN "insurance_policies"."coverage_priority" IS '1 for primary, 2 for secondary. Claims are submitted in this order.';
COMMENT ON COLUMN "insurance_policies"."effective_from" IS 'Cover start date.';
COMMENT ON COLUMN "insurance_policies"."effective_to" IS 'Cover end date. Null while active.';

CREATE INDEX "idx_insurance_patient_priority"
ON "insurance_policies" ("patient_id", "coverage_priority");

